window.kbPageData["views/entry/k-8e546bb0b57ff3a5"] = {"key":"entry/k-8e546bb0b57ff3a5","state":{"route":"entry/k-8e546bb0b57ff3a5"},"node":{"id":"k-8e546bb0b57ff3a5","mode":"k","title":"千村示范、万村整治工程","type":"事实与事件","domain":"政治理论","reading":"","intro":"","priority":100,"aliases":["“千万工程”经验"],"qs":["政治理论必刷100题#73"],"current":false,"candidates":false,"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"tags":{"专题":["governance","rural"],"主类":["事实与事件"],"出处性质":["专项题干","机构注释"],"学科":["政治理论","社会治理"],"来源主题":["农业与城乡治理"],"资料类别":["政治理论专项","非时政"]},"directorySummary":"“千村示范、万村整治”工程简称“千万工程”，于2003年在浙江启动，以农村环境整治为切入点，逐步推进乡村建设。","review":{"definition":"“千村示范、万村整治”工程简称“千万工程”，于2003年在浙江启动，以农村环境整治为切入点，逐步推进乡村建设。","explanation":"工程初期着眼于改善农村生产、生活、生态环境，通过示范带动和逐步推广推进美丽乡村建设。第73题第⑤项同时写出了农村环境整治这一切入点和美丽乡村这一建设成效，因此对应正确。","references":[],"evidence":"从农村环境整治入手，造就万千美丽乡村——“千万工程”","disposition":"独立词条","basis":"据原题和解析编释。"},"sources":[{"id":"ae3e8603d2c7cdac","label":"“千万工程”经验","topic":"农业与城乡治理","category":"非时政","text":"2.“千万工程”经验\n2003 年，时任浙江省委书记的习近平同志在广泛深入调查研究基础上，立足浙江省情\n农情和发展阶段特征，准确把握经济社会发展规律和趋势，作出了实施“千村示范、万村整\n治”工程（“千万工程”）的战略决策，在浙江近 4 万个村庄中选择 1 万个左右的行政村进\n行全面整治，把其中 1000 个左右的中心村建设成全面小康示范村，并以此为龙头，深入推\n进社会主义新农村建设。","source":{"doc":"6cbfb01fe723bba64b75","first":33,"last":34,"page":33,"file":"《2026年政府工作报告》粉笔解读.pdf"},"basis":"机构注释"}]},"questions":{"政治理论必刷100题#73":{"paper":"政治理论必刷100题","n":73,"mod":"政治理论专项","src":["国省考政治理论必刷100题.pdf",22],"asrc":["国省考政治理论必刷100题.pdf",79],"card":"e495695cb93a796449ffe6b8","links":[{"id":"k-8e546bb0b57ff3a5","role":"直接考查","why":"农村环境整治是这一乡村建设实践的起点。"}]}},"terms":{},"references":{},"topics":[{"slug":"rural","title":"乡村振兴与粮食安全"},{"slug":"governance","title":"基层治理与群众参与"}],"units":{"k-8e546bb0b57ff3a5":[["政治理论必刷100题#73"]]}};
